public class Main {
	public static void main(String[] args) {
		FastReader sc = new FastReader();
		int a = sc.nextInt();
		int b = sc.nextInt();
		int res = 0;

		for (int i = a; i <= b; i++) {
			if (isPalindromic(i)) {
				res++;
			}
		}
		System.out.println(res);
	}

	private static boolean isPalindromic(int n) {
		int num = n;
		int total = 0;
		while (num != 0) {
			total *= 10;
			total += (num % 10);
			num /= 10;
		}
		return n == total;
	}

